/*create database Sales_Project
use Sales_Project;
SELECT * FROM [dbo].[Retail_Sales_Analytics_Dataset_Final]*/

-- Total orders 
--How many sales transactions/orders are present in the Sales_Data table?
SELECT COUNT(*) AS Total_Orders FROM [dbo].[Retail_Sales_Analytics_Dataset_Final]

--What is the total sales/revenue generated by the company?
SELECT SUM(Sales) As  Total_Sales FROM [dbo].[Retail_Sales_Analytics_Dataset_Final]

--What is the total profit generated by the company?
SELECT SUM(Profit) As Total_Profit FROM [dbo].[Retail_Sales_Analytics_Dataset_Final]

--How many total units/products were sold?
SELECT SUM(Quantity) As Total_Units FROM [dbo].[Retail_Sales_Analytics_Dataset_Final]



--How much sales and profit does each category generate?
SELECT Category,Sum(Sales) AS Total_Sales,
Sum(Profit) As Total_Profit 
FROM [dbo].[Retail_Sales_Analytics_Dataset_Final]
GROUP BY Category
ORDER BY Total_Sales DESC;

--How much sales and profit does each region generate?
SELECT Region,SUM(Sales) As Total_Sales,
SUM(Profit) As Total_Profit
FROM [dbo].[Retail_Sales_Analytics_Dataset_Final]
GROUP BY Region
ORDER BY Total_Sales DESC;

--Which customer segment generates the highest sales and profit?
SELECT Segment, SUM(Sales) As Total_Sales,
Sum(Profit) AS Total_Profit
FROM [dbo].[Retail_Sales_Analytics_Dataset_Final]
GROUP BY Segment
ORDER BY Total_Sales DESC;

--TOP 10 Products 
--(Which products generate the highest sales?)
SELECT TOP 10
Product_Name,SUM(Sales) Total_Sales,
SUM(Profit) As Total_Profit
FROM [dbo].[Retail_Sales_Analytics_Dataset_Final]
GROUP BY Product_Name
ORDER BY Total_Sales DESC;

--Which products generate the lowest profit?
SELECT TOP 10
Product_Name,SUM(Sales) Total_Sales,
SUM(Profit) As Total_Profit
FROM [dbo].[Retail_Sales_Analytics_Dataset_Final]
GROUP BY Product_Name
ORDER BY Total_Profit ASC;

-- How do sales and profit change month by month?
SELECT
    YEAR(Order_Date) AS Sales_Year,
    MONTH(Order_Date) AS Sales_Month,
    SUM(Sales) AS Total_Sales,
    SUM(Profit) AS Total_Profit
FROM [dbo].[Retail_Sales_Analytics_Dataset_Final]
GROUP BY
    YEAR(Order_Date),
    MONTH(Order_Date)
ORDER BY
    Sales_Year,
    Sales_Month;


    --Advance Analysis--
 --Which products have high sales but relatively low profit?
 SELECT
    Product_Name,
    SUM(Sales) AS Total_Sales,
    SUM(Profit) AS Total_Profit,
    (SUM(Profit) / SUM(Sales)) * 100 AS Profit_Margin
FROM [dbo].[Retail_Sales_Analytics_Dataset_Final]
GROUP BY Product_Name
ORDER BY Profit_Margin ASC;

--Which categories perform best in each region?
SELECT Category,Region,
SUM(Sales) As Total_Sales,
SUM( Profit) AS Total_Profit
FROM [dbo].[Retail_Sales_Analytics_Dataset_Final]
GROUP BY Category,Region
ORDER BY Total_Sales DESC;


-- What is the highest-selling category in each region?

WITH CategoryRegionSales AS
(
    SELECT
        Region,
        Category,
        SUM(Sales) AS Total_Sales
    FROM [dbo].[Retail_Sales_Analytics_Dataset_Final]
    GROUP BY
        Region,
        Category
),
RankedCategories AS
(
    SELECT
        Region,
        Category,
        Total_Sales,
        RANK() OVER (
            PARTITION BY Region
            ORDER BY Total_Sales DESC
        ) AS Sales_Rank
    FROM CategoryRegionSales
)
SELECT
    Region,
    Category,
    Total_Sales
FROM RankedCategories
WHERE Sales_Rank = 1
ORDER BY Region;

--Top 10 Customers by Sales and Profit

SELECT TOP 10
    Customer_ID,
    SUM(Sales) AS Total_Sales,
    SUM(Profit) AS Total_Profit,
    COUNT(DISTINCT Order_ID) AS Total_Orders
FROM [dbo].[Retail_Sales_Analytics_Dataset_Final]
GROUP BY Customer_ID
ORDER BY Total_Sales DESC;

-- How did sales and profit change from 2024 to 2025?

WITH YearlySales AS
(
    SELECT
        YEAR(Order_Date) AS Sales_Year,
        SUM(Sales) AS Total_Sales,
        SUM(Profit) AS Total_Profit
    FROM [dbo].[Retail_Sales_Analytics_Dataset_Final]
    GROUP BY YEAR(Order_Date)
),
YearlyComparison AS
(
    SELECT
        Sales_Year,
        Total_Sales,
        Total_Profit,
        LAG(Total_Sales) OVER (
            ORDER BY Sales_Year
        ) AS Previous_Year_Sales,
        LAG(Total_Profit) OVER (
            ORDER BY Sales_Year
        ) AS Previous_Year_Profit
    FROM YearlySales
)
SELECT
    Sales_Year,
    Total_Sales,
    Total_Profit,
    ROUND(
        (Total_Sales - Previous_Year_Sales)
        * 100.0 / NULLIF(Previous_Year_Sales, 0), 2
    ) AS Sales_Growth_Percent,
    ROUND(
        (Total_Profit - Previous_Year_Profit)
        * 100.0 / NULLIF(Previous_Year_Profit, 0), 2
    ) AS Profit_Growth_Percent
FROM YearlyComparison
ORDER BY Sales_Year;